interface Calculation { int apply(int n); }
class DoubleValue implements Calculation {
    @Override
    public int apply(int n) { return n * 2; }
}
class Service {
    private final Calculation calculation;
    Service(Calculation calculation) { this.calculation = calculation; }
    int apply(int n) { return calculation.apply(n); }
}

class Main {
    public static void main(String[] args) {
        Service service = new Service(new DoubleValue());
        System.out.println(service.apply(4));
    }
}

class Total { int value(int n, int price) { return n * price; } }
class Text { String show(int value) { return "BDT " + value; } }

class Main {
    public static void main(String[] args) {
        Total total = new Total();
        Text text = new Text();
        System.out.println(text.show(total.value(2, 7)));
    }
}

interface Sink { void record(); }
class Count implements Sink {
    int count;
    @Override
    public void record() { count++; }
}
class Service {
    private final Sink sink;
    Service(Sink sink) { this.sink = sink; }
    void save() { sink.record(); }
}

class Main {
    public static void main(String[] args) {
        Count sink = new Count();
        Service a = new Service(sink);
        Service b = new Service(sink);
        a.save();
        b.save();
        System.out.println(sink.count);
    }
}
